    @staticmethod
    def parse(version):
        """Parse version string to a VersionInfo instance.

        >>> from semver import VersionInfo
        >>> VersionInfo.parse('3.4.5-pre.2+build.4')
        VersionInfo(major=3, minor=4, patch=5, \
prerelease='pre.2', build='build.4')

        :param version: version string
        :return: a :class:`VersionInfo` instance
        :rtype: :class:`VersionInfo`
        """
        return parse_version_info(version)

    def bump_major(self):
        """Return a new VersionInfo with major incremented by 1, minor and patch reset to 0."""
        return VersionInfo(self.major + 1, 0, 0, self.prerelease, self.build)

    def bump_minor(self):
        """Return a new VersionInfo with minor incremented by 1, patch reset to 0."""
        return VersionInfo(self.major, self.minor + 1, 0, self.prerelease, self.build)

    def bump_patch(self):
        """Return a new VersionInfo with patch incremented by 1."""
        return VersionInfo(self.major, self.minor, self.patch + 1, self.prerelease, self.build)

    def bump_prerelease(self, token='rc'):
        """Return a new VersionInfo with prerelease incremented."""
        pre = self.prerelease or (token or 'rc') + '.0'
        new_pre = _increment_string(pre)
        return VersionInfo(self.major, self.minor, self.patch, new_pre, self.build)

    def bump_build(self, token='build'):
        """Return a new VersionInfo with build incremented."""
        build = self.build or (token or 'build') + '.0'
        new_build = _increment_string(build)
        return VersionInfo(self.major, self.minor, self.patch, self.prerelease, new_build)

    def replace(self, **kwargs):
        """Return a new VersionInfo with specified components replaced."""
        major = kwargs.get('major', self.major)
        minor = kwargs.get('minor', self.minor)
        patch = kwargs.get('patch', self.patch)
        prerelease = kwargs.get('prerelease', self.prerelease)
        build = kwargs.get('build', self.build)
        return VersionInfo(major, minor, patch, prerelease, build)
